import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-04-16","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-04-16","date":"2025-04-16T00:00:00.000Z","updated":"2025-04-26T00:00:00.000Z","tags":["Ceph","RGW重构","单元测试","Ceph存储","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-04-16.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-04-16.md","lastUpdated":1780460162000}'),r={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-04-16.md"};function c(d,e,l,n,h,s){return t(),o("div",null,[...e[0]||(e[0]=[i('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><p>本次会议主要讨论了Ceph存储系统中的RGW（Rados Gateway）模块的重构相关问题，并涉及单元测试框架的选择。</p><h3 id="跨区组对象复制问题" tabindex="-1">跨区组对象复制问题 <a class="header-anchor" href="#跨区组对象复制问题" aria-label="Permalink to &quot;跨区组对象复制问题&quot;">​</a></h3><p>在跨区组对象复制过程中，当对象大小超过1MB时，复制操作的进度报告机制存在问题。具体来说，使用<code>boost::asio</code>的异步写入时，<code>yield</code>无法恢复，导致连接卡住。会议决定通过以下方式解决：</p><ul><li>使用定时器机制，定期发送进度报告，确保连接保持活跃。</li><li>由前端协程处理进度报告和最终响应的发送。</li><li>Cena将尝试实现基于定时器的解决方案，并提交PR进行进一步讨论和测试。</li></ul><h3 id="单元测试框架选择" tabindex="-1">单元测试框架选择 <a class="header-anchor" href="#单元测试框架选择" aria-label="Permalink to &quot;单元测试框架选择&quot;">​</a></h3><p>会议讨论了在Ceph项目中引入<code>Catch2</code>作为单元测试框架，以替代现有的<code>GTest</code>。<code>Catch2</code>提供更友好的测试体验，支持异常处理，适合编写协程测试。会议决定：</p><ul><li>如果没有人反对，将引入<code>Catch2</code>作为新的单元测试框架。</li><li>确保<code>Catch2</code>作为构建时依赖，不引入额外的打包或运行时依赖。</li><li>Jesse将开始使用<code>Catch2</code>编写新的单元测试，并逐步推广。</li></ul><h3 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h3><p>会议还更新了SEF Steering Committee的进展，即将发布的T版本计划在几周内冻结，开发团队需注意时间节点。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>本次会议针对Ceph RGW的重构问题进行了深入讨论，并做出了相应的决策。同时，对单元测试框架的选择也达成了一致意见。这些讨论和决策有助于提升Ceph系统的性能和稳定性。</p>',12)])])}const u=a(r,[["render",c]]);export{_ as __pageData,u as default};
